import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s,a as r,b as o,c as n,d as l,e as p}from"./chunks/M-S-SW-MB-I5.BZKmfHD5.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as d}from"./chunks/EN.P9aPnFBv.js";import{_ as c,o as m,c as u,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const A=JSON.parse('{"title":"MiBand","description":"","frontmatter":{"source_hash":"47eb878cea","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/smartwatch/miband.md","filePath":"fr/smartwatch/miband.md"}'),v={name:"fr/smartwatch/miband.md"};function f(b,i,g,y,z,x){return m(),u("div",null,[...i[0]||(i[0]=[h('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options montre intelligente<br>   MiBand</p></div><p>La version officielle de xDrip prend en charge les MiBand 2, 3 et 4, ainsi que la diffusion vers <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration" target="_blank" rel="noreferrer">WatchDrip+</a> pour les autres bracelets connectés.</p><div class="info custom-block"><p class="custom-block-title">Prérequis</p><p>Assurez-vous d&#39;avoir des valeurs de glycémie dans xDrip avant d&#39;essayer de les afficher sur votre montre.<br> Si xDrip ne reçoit pas de valeurs sur votre téléphone, elles ne s&#39;afficheront pas sur la montre.</p></div><h2 id="install" tabindex="-1">Installation <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Installation {#install}&quot;">​</a></h2><h3 id="obtain-an-authentication-key" tabindex="-1">Obtenir une clé d&#39;authentification <a class="header-anchor" href="#obtain-an-authentication-key" aria-label="Permalink to &quot;Obtenir une clé d&#39;authentification {#obtain-an-authentication-key}&quot;">​</a></h3><h4 id="if-you-already-paired-your-watch-with-the-vendor-app" tabindex="-1">Si vous avez déjà appairé votre montre avec l&#39;application du fabricant <a class="header-anchor" href="#if-you-already-paired-your-watch-with-the-vendor-app" aria-label="Permalink to &quot;Si vous avez déjà appairé votre montre avec l&#39;application du fabricant {#if-you-already-paired-your-watch-with-the-vendor-app}&quot;">​</a></h4><ul><li><p>Désappairez la montre.</p></li><li><p>Désinstallez MiFit ou Zepp, ou l&#39;application que vous utilisiez pour connecter votre montre.</p></li><li><p><strong>Supprimez les anciens fichiers de clé</strong> (avec un gestionnaire de fichiers sur votre téléphone) dans le dossier <code>freemyband</code> de la mémoire du téléphone.<br> Recommandé si vous n&#39;arrivez pas à connecter xDrip à la montre.<br><em>Remarque : le nom ci-dessous est un exemple</em></p></li></ul><img src="'+s+'" style="zoom:75%;"><h4 id="install-the-patched-app-matching-your-watch" tabindex="-1">Installer l&#39;application modifiée correspondant à votre montre <a class="header-anchor" href="#install-the-patched-app-matching-your-watch" aria-label="Permalink to &quot;Installer l&#39;application modifiée correspondant à votre montre {#install-the-patched-app-matching-your-watch}&quot;">​</a></h4><p>Rendez-vous sur <a href="https://www.freemyband.com/" target="_blank" rel="noreferrer">https://www.freemyband.com/</a></p><p>Téléchargez et installez <a href="https://www.freemyband.com/2019/08/amazfit-gtr-auth-key.html" target="_blank" rel="noreferrer">Zepp</a> pour les montres Amazfit.<br> (ou)<br> Téléchargez et installez <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">MiFit</a> pour les bracelets Xiaomi.</p><p>Connectez-vous avec votre adresse e-mail et votre mot de passe. Créez un compte si nécessaire.</p><p>Appairez votre bracelet.</p><p>Activez la visibilité de la montre. Si vous ne trouvez pas cette option, vérifiez que vous avez indiqué un âge de 18 ans ou plus.</p><p>Vérifiez qu&#39;un fichier de clé a bien été créé dans le dossier <code>freemyband</code> de la mémoire du téléphone.</p><p>Vous pouvez désinstaller l&#39;application modifiée. Ce n&#39;est pas obligatoire. Si vous voulez installer l&#39;application d&#39;origine, connectez-vous avec le même compte e-mail.</p><h2 id="not-using-watchdrip" tabindex="-1">Sans WatchDrip+ <a class="header-anchor" href="#not-using-watchdrip" aria-label="Permalink to &quot;Sans WatchDrip+ {#not-using-watchdrip}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Uniquement MiBand 2, 3 et 4</p></div><h3 id="setup-xdrip" tabindex="-1">Configurer xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurer xDrip {#setup-xdrip}&quot;">​</a></h3><p>Activez la fonction MiBand. Gardez votre montre près de votre téléphone jusqu&#39;à ce qu&#39;elle soit détectée.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser le bracelet MiBand <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><img src="'+r+'" style="zoom:80%;"><p>L&#39;adresse Mac devrait se remplir automatiquement.</p><div class="admonition xdripitem"><p class="admonition-title">Adresse Mac (FF:EE:DD:CC:BB:AA)</p><p> Laisser vide pour la recherche automatique</p></div><p><strong>Si ce n&#39;est pas le cas</strong> (inattendu)<strong>:</strong><br> Supprimez le ou les fichiers du dossier <code>freemyband</code>.<br> Ouvrez l&#39;application de montre modifiée.<br> Réessayez : désactivez puis réactivez la fonction MiBand.</p><p>Vous pouvez aussi essayer de saisir manuellement l&#39;adresse mac de la montre. Vous la trouverez dans le nom du fichier du dossier <code>freemyband</code>.<br> Par exemple, si le nom est <code>mibandFFEEDDCCBBAA.txt</code>, l&#39;adresse mac correspondante sera <code>FF:EE:DD:CC:BB:AA</code>.</p><img src="'+o+'" style="zoom:75%;"><p>Surveillez les messages toast : pendant l&#39;authentification de la montre, vous devriez voir ceci :</p><img src="'+n+'" style="zoom:75%;"><p>Si l&#39;autorisation échoue, supprimez le ou les fichiers du dossier <code>freemyband</code> et ouvrez l&#39;application modifiée pour le régénérer.</p><img src="'+l+'" style="zoom:75%;"><p>Si xDrip n&#39;arrive pas à obtenir automatiquement la clé d&#39;authentification, vous pouvez essayer de la saisir manuellement. Vous la trouverez en ouvrant le fichier.</p><img src="'+p+'" style="zoom:75%;"><p>Assurez-vous que la montre est connectée et correspond à l&#39;adresse mac avant de saisir la clé manuellement.</p><div class="admonition xdripitem"><p class="admonition-title">Clé d&#39;authentification</p><p> Définissez la clé d&#39;authentification pour MiBand4 (pour obtenir une clé d&#39;authentification, suivez les instructions sur <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">https://www.freemyband.com</a>)</p></div><p>Une fois la montre connectée et authentifiée, activez Envoyer les valeurs. Attendez la valeur suivante dans xDrip : le cadran devrait se mettre à jour.</p><div class="admonition xdripitem"><p class="admonition-title">Envoyer les valeurs <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Améliorer la date de la montre pour représenter les valeurs de glycémie. Meilleur en mmol/l - voir la documentation</p></div><p>Pour forcer la mise à jour de la montre, vous pouvez envoyer une valeur manuellement. Surveillez attentivement les messages toast.</p><div class="admonition xdripitem"><p class="admonition-title">Mettre à jour la glycémie manuellement</p></div><p>Si vous avez des problèmes d&#39;affichage du graphique, essayez de désactiver les valeurs MTU élevées.</p><div class="admonition xdripitem"><p class="admonition-title">Disable hight MTU values <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><h3 id="features" tabindex="-1">Fonctions <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Fonctions {#features}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Utiliser le bracelet MiBand <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Synchroniser les données avec les bracelets de fitness MiBand</p></div><p>Vous pouvez activer et désactiver l&#39;intégration MiBand avec l&#39;interrupteur principal. En cas de problème, n&#39;hésitez pas à la désactiver puis la réactiver pour la redémarrer.</p><div class="admonition xdripitem"><p class="admonition-title">Adresse Mac</p><p> Laisser vide pour la recherche automatique</p></div><p>L&#39;adresse mac de la montre devrait être détectée automatiquement si le champ est laissé vide. Vous pouvez la modifier manuellement et saisir les 6 valeurs hexadécimales à deux chiffres de votre montre, séparées par des deux-points.</p><div class="admonition xdripitem"><p class="admonition-title">Clé d&#39;authentification</p><p> Définissez la clé d&#39;authentification pour MiBand4 (pour obtenir une clé d&#39;authentification, suivez les instructions sur <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">https://www.freemyband.com</a>)</p></div><p>Lorsqu&#39;une adresse mac valide est trouvée, le champ de la clé apparaît aussi. S&#39;il ne se remplit pas automatiquement, vous pouvez saisir manuellement la clé d&#39;authentification de 32 caractères.</p><div class="admonition xdripitem"><p class="admonition-title">Envoyer les valeurs <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Améliorer la date de la montre pour représenter les valeurs de glycémie. Meilleur en mmol/l - voir la documentation</p></div><p>Vous devez l&#39;activer pour que les valeurs soient envoyées à la montre.</p><div class="admonition xdripitem"><p class="admonition-title">Vibrer lors des lectures <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Envoyer les alarmes <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Envoyer les notifications au bracelet pour les alarmes glycémiques</p></div><div class="admonition xdripitem"><p class="admonition-title">Envoyer les appels <span class="symbol"><img src="'+d+'" style="zoom:75%;"></span></p><p> Envoyer des notifications d&#39;appel au bracelet (Android 6+)</p></div><p>Vous pouvez activer différentes options pour que la montre vibre à chaque valeur, reçoive les alarmes ou reçoive les notifications sous forme d&#39;appels téléphoniques.</p><div class="admonition xdripitem"><p class="admonition-title">Mettre à jour la glycémie manuellement</p></div><p>Vous pouvez forcer le rafraîchissement du cadran avec Mettre à jour la glycémie manuellement.</p><div class="admonition xdripitem"><p class="admonition-title">Fonctionnalités / Écrans MiBand</p></div><p>D&#39;autres personnalisations sont disponibles dans ce menu.</p><div class="admonition xdripitem"><p class="admonition-title">Allow to use custom watchface <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Ces fonctions vous permettent de créer votre propre cadran et de modifier l&#39;image de fond.<br> Laissez-les désactivées tant que vous n&#39;avez pas correctement placé les fichiers nécessaires dans le dossier xdrip du téléphone.</p><p>Pour des astuces et des exemples, regardez <a href="https://github.com/twinko" target="_blank" rel="noreferrer">ici</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Disable hight MTU values <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Disable high MTU values (désactiver les valeurs MTU élevées) peut être utilisé en cas de problèmes d&#39;affichage du cadran.</p><h2 id="using-watchdrip" tabindex="-1">Avec WatchDrip+ <a class="header-anchor" href="#using-watchdrip" aria-label="Permalink to &quot;Avec WatchDrip+ {#using-watchdrip}&quot;">​</a></h2><h3 id="install-watchdrip" tabindex="-1">Installer <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration/" target="_blank" rel="noreferrer">WatchDrip+</a> <a class="header-anchor" href="#install-watchdrip" aria-label="Permalink to &quot;Installer [WatchDrip+](https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration/) {#install-watchdrip}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Désactivez MiBand dans xDrip si vous utilisez WatchDrip+</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser le bracelet MiBand <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div></div><h3 id="setup-xdrip-1" tabindex="-1">Configurer xDrip <a class="header-anchor" href="#setup-xdrip-1" aria-label="Permalink to &quot;Configurer xDrip {#setup-xdrip-1}&quot;">​</a></h3><p>Activez API du service Broadcast dans Paramètres -&gt; Paramètres inter applications</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Paramètres inter applications</p></div><div class="admonition xdripitem"><p class="admonition-title">API du service Broadcast <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Active la communication de xDrip avec des applications tiers en utilisant la nouvelle API</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',72)])])}const B=c(v,[["render",f]]);export{A as __pageData,B as default};
